using System.Text;
using IntercomEventing.Generators.Models;

namespace IntercomEventing.Generators;

/// <summary>
/// Writes the generated file for one <c>[IntercomEvent]</c> field: a partial declaration of every containing type with the
/// forwarding event and its <c>Event</c> view property.
/// </summary>
/// <remarks>
/// Every type is written with <c>global::</c>, so the file binds the same way in any namespace and next to any user type.
/// Namespaces use block syntax, which every C# version accepts.
/// </remarks>
internal static class IntercomEventSourceWriter
{
    private const string TaskTypeName = "global::System.Threading.Tasks.Task";
    private const string ViewInterfaceName = "global::IntercomEventing.IIntercomEvent";
    private const string EventBaseTypeName = "global::IntercomEventing.IntercomEventBase";

    //marks the members as tool-generated for code-coverage, metrics and analyzer tools
    private static readonly string GeneratedCodeAttribute =
        $"[global::System.CodeDom.Compiler.GeneratedCode(\"IntercomEventing.Generators\", \"{typeof(IntercomEventSourceWriter).Assembly.GetName().Version}\")]";

    /// <summary>
    /// The complete source of the generated file for <paramref name="field"/>.
    /// </summary>
    public static string Write(IntercomEventFieldModel field)
    {
        var source = new IndentedSourceBuilder();
        source.Line("// <auto-generated/>");
        source.Line("#nullable enable");
        if (field.SuppressedDiagnosticIds.Count > 0)
        {
            //the field already reports these where the user can suppress them; repeating them here would bypass that suppression
            source.Line("// the event's call type uses obsolete or experimental types, which its field already reports");
            source.Line($"#pragma warning disable {string.Join(", ", field.SuppressedDiagnosticIds)}");
        }
        source.BlankLine();
        if (field.NamespaceName is not null)
        {
            source.Line($"namespace {field.NamespaceName}");
            source.OpenBlock();
        }
        foreach (var containingType in field.ContainingTypes)
        {
            source.Line($"partial {containingType.Keyword} {containingType.DeclarationName}");
            source.OpenBlock();
        }

        WriteForwardingEvent(source, field);
        source.BlankLine();
        WriteViewProperty(source, field);

        for (var typeLevel = 0; typeLevel < field.ContainingTypes.Count; typeLevel++)
        {
            source.CloseBlock();
        }
        if (field.NamespaceName is not null)
        {
            source.CloseBlock();
        }
        return source.ToString();
    }

    private static void WriteForwardingEvent(IndentedSourceBuilder source, IntercomEventFieldModel field)
    {
        var eventPropertyName = IntercomEventNaming.GetEventPropertyName(field.EventName);
        var exampleHandler = $"On{field.EventName}Async";
        var exampleEvent = EscapeXml($"{field.ExampleReceiver}.{field.EventName}");

        source.Line("/// <summary>");
        source.Line("/// Occurs each time this event is raised: <c>+=</c> subscribes a handler and <c>-=</c> removes the most recently added");
        source.Line("/// equal handler.");
        source.Line("/// </summary>");
        source.Line("/// <remarks>");
        source.Line("/// Forwards to the field's <see cref=\"global::IntercomEventing.IntercomEventBase{TCall}.Raised\"/>: <c>+=</c> gives no");
        source.Line("/// subscription handle and takes no hooks, and <c>-=</c> starts the <c>OnUnsubscribed</c> hook of the subscription it");
        source.Line($"/// removes, if it has one. Subscribe through <see cref=\"{eventPropertyName}\"/> for a disposable handle, hooks or a");
        source.Line("/// per-subscription exception handler.");
        source.Line("/// </remarks>");
        source.Line("/// <example>");
        source.Line("/// <code>");
        source.Line($"/// {exampleEvent} += {exampleHandler};");
        source.Line($"/// {exampleEvent} -= {exampleHandler};");
        source.Line("/// </code>");
        source.Line("/// </example>");
        WriteForwardedAttributes(source, field);
        source.Line(GeneratedCodeAttribute);
        source.Line($"public {GetStaticModifier(field)}event global::System.Func<{field.CallTypeName}, {TaskTypeName}> {field.EventName}");
        //through the base class, whose Raised cannot be overridden: a custom event kind that declares a member named Raised
        //would otherwise capture the accessors and fail to compile here
        var eventBaseAccess = $"(({EventBaseTypeName}<{field.CallTypeName}>){field.FieldAccessExpression})";
        source.OpenBlock();
        source.Line("add");
        source.OpenBlock();
        source.Line($"{eventBaseAccess}.Raised += value;");
        source.CloseBlock();
        source.Line("remove");
        source.OpenBlock();
        source.Line($"{eventBaseAccess}.Raised -= value;");
        source.CloseBlock();
        source.CloseBlock();
    }

    private static void WriteViewProperty(IndentedSourceBuilder source, IntercomEventFieldModel field)
    {
        var eventPropertyName = IntercomEventNaming.GetEventPropertyName(field.EventName);
        var exampleProperty = EscapeXml($"{field.ExampleReceiver}.{eventPropertyName}");

        source.Line("/// <summary>");
        source.Line($"/// The subscribe-only view of the <see cref=\"{field.EventName}\"/> event, for subscriptions that need a handle,");
        source.Line("/// lifecycle hooks or a per-subscription exception handler.");
        source.Line("/// </summary>");
        source.Line("/// <remarks>");
        source.Line("/// <c>Subscribe</c> returns a handle that removes the handler when disposed, and <c>SubscribeAsync</c> also runs");
        source.Line("/// <c>OnSubscribed</c> and <c>OnUnsubscribed</c> hooks. The view has no member that raises or disposes the event,");
        source.Line("/// but it is the event object itself, typed as its subscribe-only interface.");
        source.Line("/// </remarks>");
        source.Line("/// <example>");
        source.Line("/// <code>");
        source.Line($"/// using var subscription = {exampleProperty}.Subscribe(call => Console.WriteLine(call.Metadata.RaisedAt));");
        source.Line("/// </code>");
        source.Line("/// </example>");
        WriteForwardedAttributes(source, field);
        source.Line(GeneratedCodeAttribute);
        source.Line($"public {GetStaticModifier(field)}{ViewInterfaceName}<{field.CallTypeName}> {eventPropertyName} => {field.FieldAccessExpression};");
    }

    //the field's [Obsolete] and [Experimental]: users of the members get the field author's diagnostic, and the members' own
    //use of the field is inside that context, so it reports nothing here
    private static void WriteForwardedAttributes(IndentedSourceBuilder source, IntercomEventFieldModel field)
    {
        foreach (var forwardedAttribute in field.ForwardedAttributes)
        {
            source.Line($"[{forwardedAttribute}]");
        }
    }

    private static string GetStaticModifier(IntercomEventFieldModel field)
    {
        return field.IsStatic ? "static " : string.Empty;
    }

    //type names such as Box<T> appear inside XML documentation
    private static string EscapeXml(string text)
    {
        return text.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");
    }

    /// <summary>
    /// Builds source text with four-space indentation and Allman braces, always using <c>\n</c> line endings so the
    /// generated text is identical on every operating system.
    /// </summary>
    private sealed class IndentedSourceBuilder
    {
        private const string IndentUnit = "    ";

        private readonly StringBuilder _text = new();
        private int _indentLevel;

        public void Line(string line)
        {
            for (var level = 0; level < _indentLevel; level++)
            {
                _text.Append(IndentUnit);
            }
            _text.Append(line).Append('\n');
        }

        public void BlankLine()
        {
            _text.Append('\n');
        }

        public void OpenBlock()
        {
            Line("{");
            _indentLevel++;
        }

        public void CloseBlock()
        {
            _indentLevel--;
            Line("}");
        }

        public override string ToString()
        {
            return _text.ToString();
        }
    }
}
